const mockGenerateImage = vi.fn();

const mockToBuffer = vi.fn();
const mockResize = vi.fn().mockReturnThis();
const mockWebp = vi.fn().mockReturnThis();

vi.mock('ai', () => ({
  experimental_generateImage: (...args: unknown[]) => mockGenerateImage(...args),
